// Hook is a logrus hook for redacting information from logs
type Hook struct {
	// Messages with a log level not contained in this array
	// will not be dispatched. If empty, all messages will be dispatched.
	AcceptedLevels []logrus.Level
	RedactionList  []string
	redactionKeys  []*regexp.Regexp
}

// Levels returns the user defined AcceptedLevels
// If AcceptedLevels is empty, all logrus levels are returned
func (h *Hook) Levels() []logrus.Level {
	if len(h.AcceptedLevels) == 0 {
		return logrus.AllLevels
	}
	return h.AcceptedLevels
}

// Fire redacts values in an log Entry that match
// with keys defined in the RedactionList
func (h *Hook) Fire(e *logrus.Entry) error {
	if err := h.initRedaction(); err != nil {
		return err
	}
	for _, re := range h.redactionKeys {
		// Redact based on key matching in Data fields
		for k, v := range e.Data {
			if re.MatchString(k) {
				e.Data[k] = "[REDACTED]"
				continue
			}

			e.Data[k] = redactValue(v, re)
		}

		// Redact based on text matching in the Message field
		e.Message = re.ReplaceAllString(e.Message, "$1[REDACTED]$2")
	}

	return nil
}

// redactValue preserves map keys while redacting their values, including
// values in nested maps. Other non-string values use Go's default formatting.
func redactValue(value interface{}, re *regexp.Regexp) interface{} {
	if value == nil {
		return nil
	}
	v := reflect.ValueOf(value)
	if v.Kind() == reflect.Map {
		redacted := make(map[interface{}]interface{}, v.Len())
		iter := v.MapRange()
		for iter.Next() {
			key := iter.Key().Interface()
			if re.MatchString(fmt.Sprint(key)) || sensitiveField.MatchString(fmt.Sprint(key)) {
				redacted[key] = "[REDACTED]"
			} else {
				redacted[key] = redactValue(iter.Value().Interface(), re)
			}
		}
		// Keep the common map types intact for callers that inspect log fields.
		switch value.(type) {
		case map[string]interface{}, logrus.Fields:
			result := make(map[string]interface{}, len(redacted))
			for key, val := range redacted {
				result[key.(string)] = val
			}
			return result
		case map[string]string:
			result := make(map[string]string, len(redacted))
			for key, val := range redacted {
				result[key.(string)] = fmt.Sprint(val)
			}
			return result
		}
		return redacted
	}
	if s, ok := value.(string); ok {
		return re.ReplaceAllString(s, "$1[REDACTED]$2")
	}
	return re.ReplaceAllString(fmt.Sprintf("%v", value), "$1[REDACTED]$2")
}

var sensitiveField = regexp.MustCompile(`(?i)^(?:token|subsonictoken|subsonicsalt|secret|password|apikey)$`)

func (h *Hook) initRedaction() error {
	if len(h.redactionKeys) == 0 {
		for _, redactionKey := range h.RedactionList {
			re, err := regexp.Compile(redactionKey)
			if err != nil {
				return err
			}
			h.redactionKeys = append(h.redactionKeys, re)
		}
	}
	return nil
}

func (h *Hook) redact(msg string) (string, error) {
	if err := h.initRedaction(); err != nil {
		return msg, err
	}
	for _, re := range h.redactionKeys {
		msg = re.ReplaceAllString(msg, "$1[REDACTED]$2")
	}

	return msg, nil
}
